def parse_json(json_str):
    def parse_value(tokens):
        if tokens[0] == 'null':
            tokens.pop(0)
            return None
        elif tokens[0] == 'true':
            tokens.pop(0)
            return True
        elif tokens[0] == 'false':
            tokens.pop(0)
            return False
        elif tokens[0] == '{':
            tokens.pop(0)
            result = {}
            while tokens[0] != '}':
                key = parse_value(tokens)
                if tokens[0] != ':':
                    raise ValueError("Expected ':' after key")
                tokens.pop(0)
                value = parse_value(tokens)
                result[key] = value
                if tokens[0] == ',':
                    tokens.pop(0)
            tokens.pop(0)
            return result
        elif tokens[0] == '[':
            tokens.pop(0)
            result = []
            while tokens[0] != ']':
                value = parse_value(tokens)
                result.append(value)
                if tokens[0] == ',':
                    tokens.pop(0)
            tokens.pop(0)
            return result
        elif tokens[0] == '"':
            tokens.pop(0)
            result = ''
            while tokens[0] != '"':
