def parse_json(json_str):
    def parse_value(start_index):
        if json_str[start_index:start_index + 4] == "null":
            return None, start_index + 4
        elif json_str[start_index:start_index + 5] == "true":
            return True, start_index + 5
        elif json_str[start_index:start_index + 6] == "false":
            return False, start_index + 6
        elif json_str[start_index] == '"':
            end_index = json_str.find('"', start_index + 1)
            if end_index == -1:
                raise ValueError("Unmatched quote in JSON string")
            value = json_str[start_index + 1:end_index]
            if value.count('\\') % 2 != 0:
                raise ValueError("Invalid escape sequence in JSON string")
            return value, end_index + 1
        elif json_str[start_index] in "0123456789":
            if json_str[start_index] == '0':
                if start_index + 1 < len(json_str) and json_str[start_index + 1] in "xX":
                    end_index = json_str.find('\'', start_index + 2)
                    if end_index == -1:
                        raise ValueError("Unmatched quote in JSON string")
                    value = int(json_str[start_index + 2:end_index], 16)
                    return value, end_index + 1
                else:
                    end_index = start_index
                    while end_index < len(json_str) and json_str[end_index] in "0123456789":
                        end_index += 1
                    value = int(json_str[start_index:end_index])
                    return value, end_index
            else:
                end_index = start_index
                while end_index < len(json_str) and (json_str[end_index] in "0123456789" or json_str[end_index] in "."):
                    end_index += 1
                value = float(json_str[start_index:end_index])
                return value, end_index
        elif json_str[start_index] == '[':
            value = []
            end_index = start_index + 1
            while True:
                if json_str[end_index] == ']':
                    return value, end_index + 1
                elif json_str[end_index] == ',':
                    end_index += 1
                else:
                    value_element, end_index = parse_value(end_index)
                    value.append(value_element)
        elif json_str[start_index] == '{':
            value = {}
            end_index = start_index + 1
            while True:
                if json_str[end_index] == '}':
                    return value, end_index + 1
                elif json_str[end_index] == ',':
                    end_index += 1
                else:
                    key, end_index = parse_value(end_index)
                    if json_str[end_index] != ':':
                        raise ValueError("Expected ':' in JSON object")
                    end_index += 1
                    value_element, end_index = parse_value(end_index)
                    value[key] = value_element
        else:
            raise ValueError("Invalid JSON syntax")

    def escape_sequence(start_index):
        if json_str[start_index] == '\\':
            if start_index + 1 < len(json_str):
                char = json_str[start_index + 1]
                if char in '"\\/':
                    return char, start_index + 2
                elif char == 'b':
                    return '\b', start_index + 2
                elif char == 'f':
                    return '\f', start_index + 2
                elif char == 'n':
                    return '\n', start_index + 2
                elif char == 'r':
                    return '\r', start_index + 2
                elif char == 't':
                    return '\t', start_index + 2
                elif char == 'u':
                    if start_index + 6 < len(json_str) and json_str[start_index + 6].isxdigit():
                        hex_value = json_str[start_index + 2:start_index + 6]
                        return chr(int(hex_value, 16)), start_index + 6
            raise ValueError("Invalid escape sequence")
        return None, start_index

    def parse_string(start_index):
        end_index = start_index + 1
        while end_index < len(json_str) and json_str[end_index] != '"':
            if json_str[end_index] == '\\':
                escaped_char, end_index = escape_sequence(end_index)
                if escaped_char:
