        while end_index < len(json_str) and json_str[end_index] != ']':
            if json_str[end_index] == ',':
                end_index += 1
            value, end_index = parse_value(end_index)
            if value is None:
                raise ValueError("Invalid JSON syntax")
            if end_index < len(json_str) and json_str[end_index] == ',':
                end_index += 1
        if end_index >= len(json_str) or json_str[end_index] != ']':
            raise ValueError("Unmatched bracket in JSON array")
        return json_str[start_index + 1:end_index], end_index + 1

    def parse_object(start_index):
        end_index = start_index + 1
        while end_index < len(json_str) and json_str[end_index] != '}':
