                end_index += 1
        if end_index >= len(json_str) or json_str[end_index] != '}':
            raise ValueError("Unmatched bracket in JSON object")
        return json_str[start_index + 1:end_index], end_index + 1

    def parse_json_str(start_index):
        if json_str[start_index] == '{':
            return parse_object(start_index)
        elif json_str[start_index] == '[':
            return parse_array(start_index)
        elif json_str[start_index] == '"':
