            return True, start_index + 4
        elif json_str[start_index] == 'f':
            return False, start_index + 5
        elif json_str[start_index] == 'n':
            return None, start_index + 4
        else:
            raise ValueError("Invalid JSON syntax")

    def parse_number(start_index):
        end_index = start_index
        if json_str[start_index] == '-':
            end_index += 1
        if end_index < len(json_str) and json_str[end_index].isdigit():
            end_index += 1
        if end_index < len(json_str) and json_str[end_index] == '.':
