        if not tokens:
            raise ValueError("Unexpected end of JSON string")
        token, *rest = tokens
        if token == '{':
            return parse_object(rest)
        elif token == '[':
            return parse_array(rest)
        elif token == '"':
            return parse_string(rest)
        elif token.isdigit() or token in '+-':
            return parse_number(rest)
        elif token in 'true':
            return parse_boolean(rest, True)
        elif token in 'false':
            return parse_boolean(rest, False)
        elif token in 'null':
            return parse_null(rest)
        else:
            raise ValueError(f"Unexpected token: {token}")

    def parse_object(tokens):
        obj = {}
        while tokens and tokens[0] != '}':
            if tokens[0] != '"':
                raise ValueError("Property name must be a string")
            key = parse_string(tokens[1:])
            tokens = tokens[2:]  # Skip the colon
            value = parse_next_token(tokens)
            obj[key] = value
            if tokens and tokens[0] != ',':
                raise ValueError("Expected comma or closing brace")
            tokens = tokens[1:]  # Skip the comma
        if tokens and tokens[0] != '}':
            raise ValueError("Expected closing brace")
        tokens = tokens[1:]  # Skip the closing brace
        return obj

    def parse_array(tokens):
        arr = []
