def parse_json(json_str):
    def parse_value():
        nonlocal i
        if i >= len(json_str):
            raise ValueError("Unexpected end of JSON string")

        if json_str[i] == '{':
            return parse_object()
        elif json_str[i] == '[':
            return parse_array()
        elif json_str[i] == '"':
            return parse_string()
        elif json_str[i] in '0123456789-+':
            return parse_number()
        elif json_str[i] == 't':
            if json_str[i:i+4] == 'true':
                i += 4
                return True
            else:
                raise ValueError("Unexpected token at position {}".format(i))
        elif json_str[i] == 'f':
            if json_str[i:i+5] == 'false':
                i += 5
                return False
            else:
                raise ValueError("Unexpected token at position {}".format(i))
        elif json_str[i] == 'n':
            if json_str[i:i+4] == 'null':
                i += 4
                return None
            else:
                raise ValueError("Unexpected token at position {}".format(i))
        else:
            raise ValueError("Unexpected token at position {}".format(i))

    def parse_object():
        nonlocal i
        if json_str[i] != '{':
            raise ValueError("Expected '{' at position {}".format(i))

        i += 1
        result = {}
        while i < len(json_str) and json_str[i] != '}':
            key = parse_string()
            if i >= len(json_str) or json_str[i] != ':':
                raise ValueError("Expected ':' after key at position {}".format(i))
            i += 1
            value = parse_value()
            result[key] = value
            if i < len(json_str) and json_str[i] == ',':
                i += 1
            elif i < len(json_str) and json_str[i] == '}':
                i += 1
                return result
            else:
                raise ValueError("Expected ',' or '}' at position {}".format(i))

        if i < len(json_str) and json_str[i] == '}':
            i += 1
            return result
        else:
            raise ValueError("Expected '}' at position {}".format(i))

    def parse_array():
        nonlocal i
        if json_str[i] != '[':
            raise ValueError("Expected '[' at position {}".format(i))

        i += 1
        result = []
        while i < len(json_str) and json_str[i] != ']':
            value = parse_value()
            result.append(value)
            if i < len(json_str) and json_str[i] == ',':
                i += 1
            elif i < len(json_str) and json_str[i] == ']':
                i += 1
                return result
            else:
                raise ValueError("Expected ',' or ']' at position {}".format(i))

        if i < len(json_str) and json_str[i] == ']':
            i += 1
            return result
        else:
            raise ValueError("Expected ']' at position {}".format(i))

    def parse_string():
        nonlocal i
        if json_str[i] != '"':
            raise ValueError("Expected '\"' at position {}".format(i))

        i += 1
        result = []
        while i < len(json_str) and json_str[i] != '"':
            if json_str[i] == '\\':
                i += 1
                if i >= len(json_str):
                    raise ValueError("Unexpected end of JSON string")
                if json_str[i] == 'n':
                    result.append('\n')
                elif json_str[i] == 'r':
                    result.append('\r')
                elif json_str[i] == 't':
                    result.append('\t')
                elif json_str[i] == 'b':
                    result.append('\b')
                elif json_str[i] == 'f':
                    result.append('\f')
                elif json_str[i] == '"':
                    result.append('"')
                elif json_str[i] == '\\':
                    result.append('\\')
                else:
                    raise ValueError("Invalid escape sequence at position {}".format(i))
            else:
                result.append(json_str[i])
            i += 1
        if i < len(json_str) and json_str[i] == '"':
            i += 1
            return ''.join(result)
        else:
            raise ValueError("Unexpected end of JSON string")

    def parse_number():
        nonlocal i
        start = i
        if json_str[i] == '-' or json_str[i] in '0123456789':
            i += 1
            while i < len(json_str) and json_str[i] in '0123456789':
                i += 1
            if i < len(json_str) and (json_str[i] == '.' or json_str[i] == 'e' or json_str[i] == 'E'):
                i += 1
                if json_str[i] in '0123456789':
                    i += 1
                    while i < len(json_str) and json_str[i] in '0123456789':
                        i += 1
                if i < len(json_str) and (json_str[i] == '+' or json_str[i] == '-'):
                    i += 1
                if i < len(json_str) and (json_str[i] == 'e' or json_str[i] == 'E'):
                    i += 1
                    if json_str[i] in '0123456789':
                        i += 1
                        while i < len(json_str) and json_str[i] in '0123456789':
                            i += 1
        else:
            raise ValueError("Invalid number format at position {}".format(start))

        return float(json_str[start:i])

    i = 0
    return parse_value()

